// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Set MinSum to 100
        c.SetMinSum(100);
        // Step 2: Initialize the contract
        c.Initialized();
        // Step 3: LogFile must be set to avoid revert (but LogFile doesn't affect this test)
        // We can deploy a dummy LogFile or ignore as Collect won't reach that point
        // For simplicity, set a placeholder address (any address will do for the call)
        c.SetLogFile(address(0x1234));
        // Step 4: Prank an actor, give them some ether
        address actor = address(0xABCD);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        // Put 1 wei with lockTime 0
        c.Put{value: 1}(0);
        // Step 5: Now call Collect(1) and capture whether it succeeds or reverts
        bool success;
        try c.Collect(1) { success = true; } catch { success = false; }
        // Assert: In the reference, Collect reverts because MinSum=100 > balance=1
        // In the mutant, Collect succeeds because MinSum=0 <= balance=1
        // So we assert that success is false (reference behavior)
        assertTrue(!success, "Collect should revert when MinSum=100 and balance=1");
    }
}

