// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract so SetMinSum cannot be called again
        c.Initialized();
        // This call to SetMinSum should set MinSum to 100 in reference, but 0 in bug
        c.SetMinSum(100);
        // Fund the tester with 1 wei
        vm.deal(address(this), 1 wei);
        // Put 1 wei with lock time 0
        c.Put{value: 1 wei}(0);
        // Try to collect 1 wei; reference reverts (MinSum=100 > balance=1), bug succeeds (MinSum=0)
        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: Collect reverts -> ok = false -> assertTrue(false) fails
        // Bug: Collect succeeds -> ok = true -> assertTrue(true) passes
        assertTrue(ok);
    }
}

