pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 in reference; mutant always sets MinSum to 0.
        c.SetMinSum(1);
        // Put with 0 wei and lock time 0 (balance stays 0).
        vm.deal(address(this), 0);
        vm.prank(address(this));
        c.Put(0);
        // Try Collect(1). Reference should revert (balance=0 < MinSum=1).
        // Mutant should succeed (MinSum=0, so balance >= MinSum and >= _am and timestamp > unlockTime).
        bool ok;
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference will set ok = false (revert), mutant will set ok = true (success).
        // We assert that the reference passes (ok = false). The buggy version will break this assertion (ok = true).
        assertTrue(!ok, "Reference should revert, mutant should not");
    }
}

