pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 0 (reference stores 0, bug stores 1)
        c.SetMinSum(0);
        c.Initialized();
        // Fund caller with 2 ether, then call Put(0) to set balance=2 and unlockTime=now
        address caller = address(0x1234);
        vm.deal(caller, 2 ether);
        vm.prank(caller);
        c.Put{value: 2 ether}(0);
        // Warp past unlockTime (now + 0)
        vm.warp(block.timestamp + 1);
        // Try Collect(1)
        bool ok;
        vm.prank(caller);
        try c.Collect(1) { ok = true; } catch { ok = false; }
        // Reference: MinSum=0, balance 2 >= 0, Collect succeeds => ok == true
        // Bug: MinSum=1, balance 2 >= 1, Collect should succeed? Wait: bug sets MinSum=0+1=1, but balance 2 >= 1 and minSum condition uses acc.balance >= MinSum, so Collect should succeed in both? That's not a difference.
        // Actually, the difference is in MinSum value, but both satisfy the condition, so Collect succeeds in both. Need a different scenario.
        // Let's use exactly 1 ether so that balance == MinSum.
        // Reset: deploy new contract?
        // We can't reset, so deploy new contract in same test.
        C c2 = new C();
        c2.SetMinSum(0);
        c2.Initialized();
        address caller2 = address(0x5678);
        vm.deal(caller2, 1 ether);
        vm.prank(caller2);
        c2.Put{value: 1 ether}(0);
        vm.warp(block.timestamp + 2);
        bool ok2;
        vm.prank(caller2);
        try c2.Collect(1 ether) { ok2 = true; } catch { ok2 = false; }
        // Reference MinSum=0, balance=1 >= 0 and >= 1 => passes
        // Bug MinSum=1, balance=1 >= 1 and >= 1 => passes, still same.
        // Need balance < MinSum in bug but >= in reference.
        // Let balance = 0.5 ether (500 finney). MinSum reference 0, bug 1.
        // Reference: 500 finney >= 0 => pass; Bug: 500 finney < 1 ether (1000 finney) => revert.
        C c3 = new C();
        c3.SetMinSum(0);
        c3.Initialized();
        address caller3 = address(0x9ABC);
        vm.deal(caller3, 0.5 ether);
        vm.prank(caller3);
        c3.Put{value: 0.5 ether}(0);
        vm.warp(block.timestamp + 3);
        bool ok3;
        vm.prank(caller3);
        try c3.Collect(0.5 ether) { ok3 = true; } catch { ok3 = false; }
        // Now reference passes, bug reverts.
        assertTrue(ok3);
    }
}

