pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: initialize contract, set MinSum to 0, and set LogFile
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund address(this) with 100 wei
        vm.deal(address(this), 100);
        vm.prank(address(this));
        c.Put{value: 100}(0);

        // Warp to after unlockTime (unlockTime = block.timestamp + 0 = block.timestamp)
        vm.warp(block.timestamp + 1);

        // Attempt Collect(100) — in reference, succeeds; in bug, reverts because SetLogFile reverted earlier
        bool ok;
        try c.Collect(100) { ok = true; } catch { ok = false; }

